// ---------------------------------------------------------------------------
// VALIDATOR — runs after each LLM stage. Compares stage's proposal against
// Contract; rejects proposals that violate any 'fail' closure or topology
// constraint. Replaces the current Physics-Critic-after-the-fact loop.
// ---------------------------------------------------------------------------

export function validateAgainstContract(
  proposal: any,
  contract: EngineeringContract,
): { ok: boolean; reasons: string[] } {
  const reasons: string[] = []
  // Check every 'fail' closure on the Contract; if any are unsatisfied,
  // the proposal cannot ship.
  for (const c of contract.closures) {
    if (c.status === 'fail') {
      reasons.push(`Contract closure ${c.invariant_id} FAILED: ${c.reason}`)
    }
  }
  // TODO: validate proposal-specific quantities against contract.topology
  // edges (e.g. proposal says choke is 180 A on a 1250 A bus → reject).
  return { ok: reasons.length === 0, reasons }
}

// ---------------------------------------------------------------------------
// CHAIN INTEGRATION POINT — called from scripts/serial-design-chain-v2.tsx
// AFTER brief parsing, BEFORE Generator. Returns the Contract that the
// Generator receives as immutable constraint context.
// ---------------------------------------------------------------------------

/**
 * INTENT (Sol+Fable 2026-07-27, UNIVERSAL-BRIEF-TO-HARDWARE-CLOSURE Block 1):
 * Unregistered classes used to ship `quantities: {}`, so brief scale axes like
 * `channel_count=8` never reached `contractCountFor` / tool payloads as typed
 * obligations — per-channel hardware rendered ×1. Lift brief
 * `target_performance` count metrics into the contract when absent. Never
 * overwrites an archetype- or tool-authored value. Keyed on metric key shape
 * (`*_count` / `*_qty` / unit channels|count), never a product-class table.
 */
export function seedBriefScaleCountMetrics(
  contract: EngineeringContract,
  parsedBrief: any,
): EngineeringContract {
  const tp = parsedBrief?.constraints?.target_performance
  const metrics: Array<{ key_metric?: string; metric?: string; name?: string; value?: unknown; unit?: string }> =
    Array.isArray(tp?.metrics) && tp.metrics.length > 0
      ? tp.metrics
      : tp?.key_metric
        ? [{ key_metric: tp.key_metric, value: tp.value, unit: tp.unit }]
        : []
  if (metrics.length === 0) return contract
  if (!contract.quantities) contract.quantities = {}
  for (const m of metrics) {
    const key = String(m?.key_metric ?? m?.metric ?? m?.name ?? '').trim()
    if (!key) continue
    const unit = String(m?.unit ?? '').toLowerCase()
    const isCountKey = /_(count|qty|quantity|number)$/i.test(key)
      || /^(channels?|count)$/i.test(unit)
      || unit === 'channels'
    if (!isCountKey) continue
    const raw = Number(m?.value)
    if (!Number.isFinite(raw) || raw < 1 || raw >= 1e7) continue
    const value = Math.round(raw)
    if (contract.quantities[key]?.value !== undefined) continue
    contract.quantities[key] = q(
      value,
      '',
      'dimensionless',
      'rated',
      'system',
      'brief',
      {
        source_detail: `brief.constraints.target_performance.metrics[${key}] — scale multiplicity axis`,
        condition: 'brief hard target',
      },
    )
  }
  return contract
}

/** Hard brief scalars we seed as typed ledger targets (P3 — finish Phase 1). */
const BRIEF_HARD_SCALAR_SEED: ReadonlyArray<{
  key: RegExp
  unit: string
  family: UnitFamily
  /** When true, value is a per-channel figure (compliance must not steal for aggregates). */
  perChannel?: boolean
}> = [
  { key: /^(voltage_range_v|channel_voltage_range_v|voltage_range)$/i, unit: 'V', family: 'voltage', perChannel: true },
  { key: /^(current_range_a|channel_current_magnitude_a|current_range)$/i, unit: 'A', family: 'current', perChannel: true },
  { key: /^(max_simultaneous_dissipation_w|aggregate_.*dissipation_w|total_instrument_dissipation_w)$/i, unit: 'W', family: 'power' },
  { key: /^(voltage_measurement_accuracy_pct_fs|voltage_measurement_accuracy)$/i, unit: '%_FS', family: 'dimensionless' },
  { key: /^(current_measurement_accuracy_pct_fs|current_measurement_accuracy)$/i, unit: '%_FS', family: 'dimensionless' },
  // INTENT: cell-bay operating envelope is a HARD brief range (15–45 °C on the
  // benchtop cycler). Stability alone was seeded; min/max were left UNVERIFIED
  // and floored Exec Summary / Verification / Brief to 0–4 (cold-v15 punchlist).
  { key: /^(cell_bay_temp_min_c|cell_bay_temperature_min)/i, unit: '°C', family: 'temperature' },
  { key: /^(cell_bay_temp_max_c|cell_bay_temperature_max)/i, unit: '°C', family: 'temperature' },
  { key: /^(cell_bay_temp_stability_c|cell_bay_temperature_stability)/i, unit: '°C', family: 'temperature' },
  { key: /^(data_logging_rate_hz_per_channel|logging_rate)/i, unit: 'Hz', family: 'frequency', perChannel: true },
  { key: /^(design_life_years)$/i, unit: 'years', family: 'dimensionless' },
  { key: /^(design_life_channel_hours)$/i, unit: 'channel-hours', family: 'dimensionless' },
  { key: /^(prototype_bom_cost_ceiling_gbp|unit_cost_ceiling|cost_ceiling)/i, unit: 'GBP', family: 'currency' },
]

/**
 * INTENT (Sol+Fable P3/P4): Count-only seeding left 13/29 brief constraints
 * UNVERIFIED and let a per-channel 25 W figure satisfy a 200 W aggregate demand.
 * Seed hard scalar targets from the brief and ensure an aggregate dissipation
 * entry exists (either stated, or per-channel × channel_count).
 */
export function seedBriefHardScalarMetrics(
  contract: EngineeringContract,
  parsedBrief: any,
): EngineeringContract {
  const tp = parsedBrief?.constraints?.target_performance
  const metrics: Array<{ key_metric?: string; metric?: string; name?: string; value?: unknown; unit?: string }> =
    Array.isArray(tp?.metrics) && tp.metrics.length > 0
      ? tp.metrics
      : tp?.key_metric
        ? [{ key_metric: tp.key_metric, value: tp.value, unit: tp.unit }]
        : []
  if (!contract.quantities) contract.quantities = {}

  for (const m of metrics) {
    const key = String(m?.key_metric ?? m?.metric ?? m?.name ?? '').trim()
    if (!key) continue
    const spec = BRIEF_HARD_SCALAR_SEED.find((s) => s.key.test(key))
    if (!spec) continue
    const raw = Number(m?.value)
    if (!Number.isFinite(raw) || raw <= 0 || raw >= 1e12) continue
    if (contract.quantities[key]?.value !== undefined) continue
    contract.quantities[key] = q(
      raw,
      spec.unit,
      spec.family,
      'rated',
      'system',
      'brief',
      {
        source_detail: `brief.constraints.target_performance.metrics[${key}] — hard scalar target`
          + (spec.perChannel ? ' (per-channel; not an aggregate)' : ''),
        condition: spec.perChannel ? 'per_channel brief hard target' : 'brief hard target',
      },
    )
  }

  // P4: aggregate dissipation must exist as its OWN key. Prefer a stated
  // aggregate; else derive from per-channel × channel_count when both present.
  const qmap = contract.quantities
  const hasAggregate = Object.keys(qmap).some((k) =>
    /^(max_simultaneous_dissipation_w|aggregate_.*dissipation_w|total_instrument_dissipation_w)$/i.test(k)
      && Number(qmap[k]?.value) > 0,
  )
  if (!hasAggregate) {
    const perCh = Number(
      qmap.channel_max_dissipation_w?.value
      ?? qmap.per_channel_dissipation_w?.value
      ?? qmap.per_channel_power_duty_w?.value,
    )
    const nCh = Number(qmap.channel_count?.value)
    if (Number.isFinite(perCh) && perCh > 0 && Number.isFinite(nCh) && nCh >= 2) {
      qmap.aggregate_dissipation_w = q(
        perCh * nCh,
        'W',
        'power',
        'rated',
        'system',
        'calculator',
        {
          source_detail: 'channel_max_dissipation_w × channel_count',
          condition: 'aggregate simultaneous',
          from: ['channel_max_dissipation_w', 'channel_count'],
          formula: 'channel_max_dissipation_w * channel_count',
        },
      )
    }
  } else if (qmap.max_simultaneous_dissipation_w?.value !== undefined
    && qmap.aggregate_dissipation_w?.value === undefined) {
    // Alias so compliance matchers that look for aggregate_* resolve.
    const agg = Number(qmap.max_simultaneous_dissipation_w.value)
    if (Number.isFinite(agg) && agg > 0) {
      qmap.aggregate_dissipation_w = q(
        agg,
        'W',
        'power',
        'rated',
        'system',
        'brief',
        {
          source_detail: 'alias of max_simultaneous_dissipation_w',
          condition: 'aggregate simultaneous',
          from: ['max_simultaneous_dissipation_w'],
        },
      )
    }
  }

  return contract
}

// ---------------------------------------------------------------------------
// formula_e_rear_mgu — rear MGU + MCU (SiC inverter) only (2026-07-28)
// INTENT: Seed public GEN4 outer-box + trial assumptions so the MGU/MCU
// analytical tool pack has HARD inputs. Not a full race-car archetype —
// front MGU, chassis, and battery pack are out of perimeter.
// ---------------------------------------------------------------------------
registerArchetype('formula_e_rear_mgu', (brief: any) => {
  const desc = String(brief?.product_description ?? brief?.original_text ?? '')
  const tp = brief?.constraints?.target_performance ?? {}
  const u = String(tp.unit ?? 'kW').toLowerCase()

  // Rear axle electrical power cap (DC-bus flow) — public GEN4 ≤350 kW rear.
  const rearAxleKw = (() => {
    const m = desc.match(/(?:≤|<=|max(?:imum)?|up\s+to)\s*(\d{2,4})\s*kW\s+rear/i)
      ?? desc.match(/(\d{2,4})\s*kW\s+rear/i)
    if (m) return Math.min(350, parseFloat(m[1]))
    if (Number(tp.value ?? 0) > 0 && (u === 'kw' || u === 'kilowatt' || u === 'kilowatts')) {
      return Math.min(350, Number(tp.value))
    }
    return 350
  })()

  // GOTCHA (2026-07-29): extractRangeFromDesc averages capture groups — unusable
  // for a window floor/ceiling. Parse the Vdc window endpoints explicitly so
  // assumed_vdc_min_v = 600 (not 750 = mid of 600–900).
  const vDcWindow = desc.match(/(?:dc\s*bus|vdc|usable\s+dc\s+window)\s*[:=]?\s*(\d{3})\s*[-–]\s*(\d{3})\s*V/i)
  const vDcMin = vDcWindow
    ? parseFloat(vDcWindow[1])
    : extractRangeFromDesc(desc, /(?:dc\s*bus|vdc).{0,40}?(\d{3})\s*V/i, 600)
  const vDcMaxMatch = desc.match(/(?:600|650)\s*[-–]\s*(\d{3})\s*V/i)
  const vDcMax = vDcWindow
    ? parseFloat(vDcWindow[2])
    : (vDcMaxMatch
      ? parseFloat(vDcMaxMatch[1])
      : extractRangeFromDesc(desc, /(?:absolute|vehicle)\s+max(?:imum)?\s+(\d{3,4})\s*V/i, 900))
  const vDcNom = (vDcMin + Math.min(vDcMax, 1000)) / 2
  // DECISION (2026-07-28 SOL overnight): peak electrical cap stays 350 kW; continuous
  // design duty for loss tools is a trial assumption 250 kW. Phase current must close
  // P ≈ √3 · V_ac · I_ph at Vdc,min — with V_ac≈Vdc/√2, I_ph ≈ 350e3/(√3·600/√2) ≈ 528 A.
  // Default 530 Arms (was 450 — envelope tool only reached ~298 kW at 600 V).
  const continuousKw = Math.min(rearAxleKw, 250)
  const phaseCurrentNeededA = Math.ceil(
    (rearAxleKw * 1000) / (Math.sqrt(3) * (vDcMin / Math.SQRT2)),
  )
  const phaseCurrentMaxA = extractRangeFromDesc(
    desc,
    /(\d{2,4})\s*A\s*(?:phase|rms|iph)/i,
    Math.max(530, phaseCurrentNeededA),
  )
  const baseSpeedRpm = extractRangeFromDesc(desc, /(\d{4,5})\s*-?\s*(\d{4,5})?\s*rpm/i, 40000)
  // DECISION (2026-07-29): MGU shaft power is DC-bus × η_inv × η_mgu — NOT a
  // lumped 0.92 that also folds gear loss. Critic HIGH on 0733: prose cited
  // 350 kW electrical + 322 kW shaft + η_machine=0.985 (inconsistent). Gear
  // loss lands on gear_output_power_kw separately.
  const etaInvSeed = 0.985
  const etaMguSeed = 0.97
  const etaGearSeed = 0.97
  const omega = baseSpeedRpm * 2 * Math.PI / 60
  const mguShaftPowerKw = Math.round(rearAxleKw * etaInvSeed * etaMguSeed * 10) / 10
  const gearOutputPowerKw = Math.round(mguShaftPowerKw * etaGearSeed * 10) / 10
  const shaftTorqueNm = extractRangeFromDesc(desc, /(\d{2,3})\s*-?\s*(\d{2,3})?\s*Nm/i,
    Math.round((mguShaftPowerKw * 1000) / Math.max(omega, 1) * 10) / 10)
  // INTENT: brief band 6:1–12:1 must stay as FLOOR/CEILING identities — aliasing
  // them to the chosen ratio made gear_ratio_max=8 vs brief 12 look like a miss
  // under any higher-is-better path (self-audit COMPLIANCE_FAIL on 0733).
  // GOTCHA: extractRangeFromDesc on "6:1 to 12:1" returns 6 (first capture) —
  // never use that as the chosen homologated ratio.
  const gearRatioBand = (() => {
    const metrics = brief?.constraints?.target_performance?.metrics
    let min = 6
    let max = 12
    if (Array.isArray(metrics)) {
      for (const m of metrics) {
        const k = String((m as { key_metric?: string })?.key_metric || '').toLowerCase()
        const v = Number((m as { value?: number })?.value)
        if (!Number.isFinite(v) || v <= 0) continue
        if (k === 'gear_ratio_min') min = v
        if (k === 'gear_ratio_max') max = v
      }
    }
    return { min, max }
  })()
  const gearRatio = (() => {
    const bandHit = desc.match(
      /gear\s*ratio[^0-9]{0,24}(\d{1,2}(?:\.\d+)?)\s*:?\s*1?\s*(?:to|–|-|—)\s*(\d{1,2}(?:\.\d+)?)/i,
    )
    if (bandHit) {
      // Trial homologation seed inside the stated window (not the band floor).
      const lo = parseFloat(bandHit[1])
      const hi = parseFloat(bandHit[2])
      if (Number.isFinite(lo) && Number.isFinite(hi) && hi >= lo) {
        const seed = 8
        if (seed >= lo && seed <= hi) return seed
        return Math.round((lo + hi) / 2)
      }
    }
    const single = desc.match(/gear\s*ratio[^0-9]{0,12}(\d{1,2}(?:\.\d+)?)\s*:?\s*1?\b/i)
    if (single) {
      const v = parseFloat(single[1])
      if (Number.isFinite(v) && v >= gearRatioBand.min && v <= gearRatioBand.max) return v
    }
    return 8
  })()
  const wheelRadiusM = 0.33
  const massCapKg = Number(brief?.constraints?.max_mass_kg?.value ?? 35)
  // INTENT (2026-07-29 SOL): brief metric assumed_coolant_inlet_c=60 is the seed;
  // extractRangeFromDesc on "50–65 °C" was landing ~55 and FAILING compliance as a floor.
  const coolantFromMetric = (() => {
    const metrics = brief?.constraints?.target_performance?.metrics
    if (!Array.isArray(metrics)) return NaN
    for (const m of metrics) {
      const k = String((m as { key_metric?: string })?.key_metric || '').toLowerCase()
      if (k.includes('coolant_inlet')) {
        const v = Number((m as { value?: number })?.value)
        if (Number.isFinite(v) && v > 0) return v
      }
    }
    return NaN
  })()
  const coolantInletC = Number.isFinite(coolantFromMetric)
    ? coolantFromMetric
    : extractRangeFromDesc(desc, /inlet\s+(\d{2})\s*-?\s*(\d{2})?\s*°?\s*C/i, 60)
  const coolantFlowLMin = extractRangeFromDesc(desc, /(\d{1,2})\s*-?\s*(\d{2})?\s*L\s*\/\s*min/i, 15)
  const fswKhz = extractRangeFromDesc(desc, /(\d{1,3})\s*kHz/i, 40)
  const polePairs = 2
  const airgapBT = 0.9
  const electricLoading = 60000

  const quantities: Record<string, Quantity> = {
    rear_axle_electrical_power_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'system', 'brief', {
      source_detail: 'FIA GEN4-class rear DC-bus electrical power-flow cap (public outer box)',
    }),
    continuous_power_kw: q(continuousKw, 'kW', 'power', 'continuous', 'system', 'brief', {
      source_detail: 'trial continuous design duty for loss tools (peak remains rear_axle_electrical_power_kw)',
    }),
    // DECISION (2026-07-28 SOL overnight): nameplate principals must survive the
    // peak electrical cap (350 kW). continuous_power_kw stays the loss-tool duty;
    // these aliases are the envelope/rating stamps (stem match per principal).
    traction_motor_power_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'module', 'calculator', {
      source_detail: 'alias of rear_axle_electrical_power_kw for IPMSM nameplate + envelope sizing',
      from: ['rear_axle_electrical_power_kw'],
    }),
    traction_inverter_power_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'module', 'calculator', {
      source_detail: 'alias of rear_axle_electrical_power_kw for SiC MCU nameplate + envelope sizing',
      from: ['rear_axle_electrical_power_kw'],
    }),
    dc_bus_voltage_v: q(vDcNom, 'V', 'voltage', 'rated', 'system', 'brief', {
      source_detail: 'mid of assumed usable DC window under race SoC/temp',
    }),
    v_dc_min_v: q(vDcMin, 'V', 'voltage', 'min', 'system', 'brief'),
    v_dc_max_v: q(Math.min(vDcMax, 1000), 'V', 'voltage', 'max', 'system', 'brief', {
      source_detail: 'usable window; absolute vehicle max 1000 V',
    }),
    // INTENT (2026-07-29 SOL Verification spine): brief metric keys must exist as
    // delivered quantities — UNVERIFIED on Exec/Brief was identity miss, not physics miss.
    assumed_vdc_min_v: q(vDcMin, 'V', 'voltage', 'min', 'system', 'brief', {
      source_detail: 'alias of v_dc_min_v for brief-compliance identity match',
      from: ['v_dc_min_v'],
    }),
    assumed_vdc_max_v: q(Math.min(vDcMax, 1000), 'V', 'voltage', 'max', 'system', 'brief', {
      source_detail: 'alias of v_dc_max_v for brief-compliance identity match',
      from: ['v_dc_max_v'],
    }),
    max_system_voltage_v: q(1000, 'V', 'voltage', 'max', 'system', 'brief', {
      source_detail: 'absolute vehicle / insulation-class ceiling (brief); operating window is assumed_vdc_*',
    }),
    max_rotor_speed_rpm: q(100000, 'rpm', 'dimensionless', 'max', 'module', 'brief', {
      source_detail: 'FIA/regulatory rotor-speed ceiling the retention stack is designed against (base speed is separate)',
    }),
    mgu_shaft_torque_max_nm: q(
      extractRangeFromDesc(desc, /(\d{2,3})\s*-?\s*(\d{2,3})?\s*Nm/i, 120),
      'Nm', 'force', 'max', 'module', 'brief', {
        source_detail: 'upper illustrative MGU shaft-torque band from brief (dyno replaces)',
      },
    ),
    // INTENT (2026-07-29 SOL Verification spine): remaining brief metric keys must
    // exist as delivered quantities so Exec/Brief stop UNVERIFIED on identity miss.
    rear_electrical_power_cap_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'system', 'brief', {
      source_detail: 'alias of rear_axle_electrical_power_kw for brief-compliance identity',
      from: ['rear_axle_electrical_power_kw'],
    }),
    // Brief parser sometimes emits peak_*_power_kw — alias so compliance is not UNVERIFIED.
    peak_electrical_power_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'system', 'brief', {
      source_detail: 'alias of rear_axle_electrical_power_kw for brief peak-electrical identity',
      from: ['rear_axle_electrical_power_kw'],
    }),
    peak_mechanical_power_kw: q(mguShaftPowerKw, 'kW', 'power', 'peak', 'module', 'calculator', {
      source_detail: `MGU shaft = P_dc×η_inv×η_mgu (seeds ${etaInvSeed}×${etaMguSeed}); tools overwrite`,
      from: ['rear_axle_electrical_power_kw'],
    }),
    mgu_shaft_power_kw: q(mguShaftPowerKw, 'kW', 'power', 'peak', 'module', 'calculator', {
      source_detail: 'seed MGU shaft power before motor:ipmsm-analytical-sizing overwrite',
      from: ['rear_axle_electrical_power_kw'],
    }),
    gear_output_power_kw: q(gearOutputPowerKw, 'kW', 'power', 'peak', 'module', 'calculator', {
      source_detail: `post-gear axle power = shaft×η_gear (seed ${etaGearSeed})`,
      from: ['mgu_shaft_power_kw'],
    }),
    inverter_efficiency: q(etaInvSeed, '', 'dimensionless', 'rated', 'module', 'brief', {
      source_detail: 'seed — overwritten by inverter:sic-loss',
    }),
    mgu_efficiency: q(etaMguSeed, '', 'dimensionless', 'rated', 'module', 'brief', {
      source_detail: 'seed — overwritten by motor:loss-point',
    }),
    gear_efficiency: q(etaGearSeed, '', 'dimensionless', 'rated', 'module', 'brief', {
      source_detail: 'seed — overwritten by gear:traction-ratio',
    }),
    peak_power_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'system', 'brief', {
      source_detail: 'alias of rear_axle_electrical_power_kw for generic peak_power identity',
      from: ['rear_axle_electrical_power_kw'],
    }),
    rear_regen_electrical_cap_kw: q(rearAxleKw, 'kW', 'power', 'peak', 'system', 'brief', {
      source_detail: 'GEN4 rear regen electrical cap (same public outer box as motoring for trial)',
      from: ['rear_axle_electrical_power_kw'],
    }),
    assumed_mgu_mcu_mass_cap_kg: q(massCapKg > 0 ? massCapKg : 35, 'kg', 'mass', 'max', 'system', 'brief', {
      source_detail: 'alias of mgu_mcu_mass_cap_kg for brief-compliance identity',
      from: ['mgu_mcu_mass_cap_kg'],
    }),
    assumed_coolant_inlet_c: q(coolantInletC, '°C', 'temperature', 'rated', 'system', 'brief', {
      source_detail: 'alias of coolant_inlet_c for brief-compliance identity',
      from: ['coolant_inlet_c'],
    }),
    min_lamination_thickness_mm: q(0.05, 'mm', 'length', 'min', 'module', 'brief', {
      source_detail: 'brief hard regulatory outer-box (lamination thickness floor)',
    }),
    winding_temp_limit_c: q(180, '°C', 'temperature', 'max', 'module', 'brief', {
      source_detail: 'brief winding insulation temperature ceiling',
    }),
    magnet_temp_limit_c: q(150, '°C', 'temperature', 'max', 'module', 'brief', {
      source_detail: 'brief magnet temperature ceiling',
    }),
    rotor_stress_margin_min: q(1.5, 'ratio', 'dimensionless', 'min', 'module', 'brief', {
      source_detail: 'brief minimum rotor stress safety factor — HOLD if tool margin is below',
    }),
    ac_output_voltage_v: q(Math.round(vDcNom / Math.SQRT2), 'V', 'voltage', 'rated', 'module', 'calculator', {
      source_detail: '≈ Vdc/√2 modulation headroom proxy for 3-ph bridge',
    }),
    phase_current_max_a: q(phaseCurrentMaxA, 'A', 'current', 'peak', 'module', 'brief'),
    mgu_base_speed_rpm: q(baseSpeedRpm, 'rpm', 'dimensionless', 'rated', 'module', 'brief'),
    mgu_shaft_torque_nm: q(shaftTorqueNm, 'Nm', 'force', 'rated', 'module', 'calculator', {
      source_detail: 'P=Tω at base speed for MGU shaft (η_inv×η_mgu on DC cap); dyno replaces',
      formula: 'T = P_dc * η_inv * η_mgu / ω_base',
      from: ['rear_axle_electrical_power_kw', 'mgu_base_speed_rpm'],
    }),
    gear_ratio: q(gearRatio, 'ratio', 'dimensionless', 'rated', 'module', 'brief', {
      source_detail: `chosen homologated ratio within brief band ${gearRatioBand.min}–${gearRatioBand.max}`,
    }),
    // Brief band endpoints are the design-space floor/ceiling — NOT the chosen ratio.
    gear_ratio_min: q(gearRatioBand.min, 'ratio', 'dimensionless', 'min', 'module', 'brief', {
      source_detail: 'brief gear-ratio band floor (chosen gear_ratio must be ≥ this)',
    }),
    gear_ratio_max: q(gearRatioBand.max, 'ratio', 'dimensionless', 'max', 'module', 'brief', {
      source_detail: 'brief gear-ratio band ceiling (chosen gear_ratio must be ≤ this)',
    }),
    wheel_radius_m: q(wheelRadiusM, 'm', 'length', 'rated', 'system', 'brief'),
    mgu_mcu_mass_cap_kg: q(massCapKg > 0 ? massCapKg : 35, 'kg', 'mass', 'max', 'system', 'brief'),
    coolant_inlet_c: q(coolantInletC, '°C', 'temperature', 'rated', 'system', 'brief'),
    coolant_flow_l_min: q(coolantFlowLMin, 'L/min', 'flow_rate', 'rated', 'system', 'brief'),
    // Brief parser emits coolant_flow_*_l_per_min — alias for identity match.
    coolant_flow_min_l_per_min: q(coolantFlowLMin, 'L/min', 'flow_rate', 'min', 'system', 'brief', {
      source_detail: 'alias of coolant_flow_l_min for brief-compliance identity',
      from: ['coolant_flow_l_min'],
    }),
    coolant_flow_max_l_per_min: q(coolantFlowLMin, 'L/min', 'flow_rate', 'max', 'system', 'brief', {
      source_detail: 'alias of coolant_flow_l_min — chosen flow within brief 10–20 L/min band',
      from: ['coolant_flow_l_min'],
    }),
    switching_frequency_khz: q(fswKhz, 'kHz', 'frequency', 'rated', 'module', 'brief'),
    mcu_switching_frequency_min_khz: q(fswKhz, 'kHz', 'frequency', 'min', 'module', 'brief', {
      source_detail: 'alias of switching_frequency_khz for brief band floor identity',
      from: ['switching_frequency_khz'],
    }),
    mcu_switching_frequency_max_khz: q(fswKhz, 'kHz', 'frequency', 'max', 'module', 'brief', {
      source_detail: 'alias of switching_frequency_khz for brief band ceiling identity',
      from: ['switching_frequency_khz'],
    }),
    // Illustrative / race-mean band identities → delivered design setpoints.
    race_mean_electrical_throughput_min_kw: q(continuousKw, 'kW', 'power', 'min', 'system', 'brief', {
      source_detail: 'alias of continuous_power_kw — race-mean design duty within brief 150–250 kW band',
      from: ['continuous_power_kw'],
    }),
    race_mean_electrical_throughput_max_kw: q(continuousKw, 'kW', 'power', 'max', 'system', 'brief', {
      source_detail: 'alias of continuous_power_kw — race-mean design duty within brief 150–250 kW band',
      from: ['continuous_power_kw'],
    }),
    illustrative_mgu_base_speed_min_rpm: q(baseSpeedRpm, 'rpm', 'dimensionless', 'min', 'module', 'brief', {
      source_detail: 'alias of mgu_base_speed_rpm — design base within illustrative 30–50 krpm band',
      from: ['mgu_base_speed_rpm'],
    }),
    illustrative_mgu_base_speed_max_rpm: q(baseSpeedRpm, 'rpm', 'dimensionless', 'max', 'module', 'brief', {
      source_detail: 'alias of mgu_base_speed_rpm — design base within illustrative 30–50 krpm band',
      from: ['mgu_base_speed_rpm'],
    }),
    illustrative_shaft_torque_min_nm: q(shaftTorqueNm, 'Nm', 'force', 'min', 'module', 'brief', {
      source_detail: 'alias of mgu_shaft_torque_nm — design torque within illustrative band',
      from: ['mgu_shaft_torque_nm'],
    }),
    illustrative_shaft_torque_max_nm: q(shaftTorqueNm, 'Nm', 'force', 'max', 'module', 'brief', {
      source_detail: 'alias of mgu_shaft_torque_nm — design torque within illustrative band',
      from: ['mgu_shaft_torque_nm'],
    }),
    pole_pairs: q(polePairs, '', 'dimensionless', 'rated', 'module', 'brief'),
    airgap_b_t: q(airgapBT, 'T', 'dimensionless', 'rated', 'module', 'brief'),
    electric_loading_a_per_m: q(electricLoading, 'A/m', 'dimensionless', 'rated', 'module', 'brief'),
    mosfet_rdson_mohm: q(8, 'mΩ', 'dimensionless', 'rated', 'module', 'brief', {
      source_detail: 'illustrative SiC Rdson — replace with device datasheet',
    }),
    // INTENT (2026-07-29): seed pack envelope; applyUniversalContractSizing
    // syncTractionPackEnclosureFromPrincipals rewrites from stamped motor/MCU/gear.
    // 0806 critic: 0.018 m³ shell vs ~47 L principals — seed must not starve the pack.
    design_envelope_width_mm: q(520, 'mm', 'length', 'max', 'system', 'calculator', {
      source_detail: 'seed IPMSM+SiC+gear axial pack width — sizing sync overwrites',
    }),
    design_envelope_depth_mm: q(280, 'mm', 'length', 'max', 'system', 'calculator', {
      source_detail: 'seed pack depth — sizing sync overwrites from principals',
    }),
    design_envelope_height_mm: q(220, 'mm', 'length', 'max', 'system', 'calculator', {
      source_detail: 'seed pack height — sizing sync overwrites from principals',
    }),
    enclosure_volume_m3: q(
      Math.round((520 * 280 * 220) / 1e9 * 1e6) / 1e6,
      'm³', 'volume', 'max', 'system', 'calculator', {
        source_detail: '0.520×0.280×0.220 m seed traction pack — sizing sync overwrites',
      },
    ),
  }

  const topology: TopologyEdge[] = [
    {
      from_part: 'hv_battery_dc_bus',
      to_part: 'rear_mcu_inverter',
      mechanism: 'electrical_bus',
      constraint_kind: 'voltage_rating',
      required_value: Math.min(vDcMax, 1000),
      required_unit: 'V',
    },
    {
      from_part: 'rear_mcu_inverter',
      to_part: 'rear_mgu_stator',
      mechanism: 'electrical_bus',
      constraint_kind: 'current_rating',
      required_value: phaseCurrentMaxA,
      required_unit: 'A',
      required_margin_factor: 1.1,
    },
    {
      from_part: 'coolant_loop',
      to_part: 'rear_mgu_mcu_cold_plates',
      mechanism: 'fluid_loop',
      constraint_kind: 'flow_capacity',
      required_value: coolantFlowLMin,
      required_unit: 'L/min',
    },
  ]

  // DECISION (2026-07-28 SOL / raised 2026-07-29): macro word_names match the
  // universal TRACTION_DRIVE_MODULE_FLOORS ids. £/kW specialty low-volume band
  // (not automotive volume, not Jaguar SKUs) — ~£80/kW motor + ~£50/kW SiC MCU
  // so materials clear the independent £80/kW power-family floor once grounded.
  const motorMacroGbp = Math.round(rearAxleKw * 80)
  const sicMacroGbp = Math.round(rearAxleKw * 50)
  const gearMacroGbp = Math.max(4500, Math.round(rearAxleKw * 15))
  const macros: MacroAssemblyPrice[] = [
    {
      word_name: 'traction_ipmsm_motor_generator',
      unit_price_gbp: motorMacroGbp,
      dimension_basis: 'each',
      dimension_value: 1,
      total_gbp: motorMacroGbp,
      source_detail: `trial specialty low-volume IPMSM ≈ £80/kW × ${rearAxleKw} kW (replace with team quote)`,
    },
    {
      word_name: 'sic_traction_inverter',
      unit_price_gbp: sicMacroGbp,
      dimension_basis: 'each',
      dimension_value: 1,
      total_gbp: sicMacroGbp,
      source_detail: `trial specialty SiC MCU ≈ £50/kW × ${rearAxleKw} kW (replace with team quote)`,
    },
    {
      word_name: 'reduction_gear_stage',
      unit_price_gbp: gearMacroGbp,
      dimension_basis: 'each',
      dimension_value: 1,
      total_gbp: gearMacroGbp,
      source_detail: 'trial gear stage within manufacturer perimeter (≈ £15/kW floor)',
    },
  ]

  return {
    product_class: 'formula_e_rear_mgu',
    brief_summary: `Formula E GEN4-class rear MGU + MCU (SiC inverter) + gear/cooling interfaces — `
      + `${rearAxleKw} kW rear electrical, ~${shaftTorqueNm} Nm @ ${baseSpeedRpm} rpm base, `
      + `Vdc ${vDcMin}–${Math.min(vDcMax, 1000)} V. Front MGU and full vehicle out of scope.`,
    quantities,
    topology,
    macro_assembly_prices: macros,
    closures: [],
  }
})

export function buildContractForChain(
  productClass: string,
  parsedBrief: any,
): EngineeringContract {
  const contract = buildContract(productClass, parsedBrief) ?? {
    product_class: productClass,
    brief_summary: `Engineering Contract not registered for ${productClass} — falling back to LLM-only chain.`,
    quantities: {},
    topology: [],
    macro_assembly_prices: [],
    closures: [],
  }
  // Always fill ABSENT brief scale counts + hard scalar targets (registered
  // archetypes keep their own authored values; unregistered classes stop
  // shipping an empty / count-only ledger).
  return seedBriefHardScalarMetrics(
    seedBriefScaleCountMetrics(contract, parsedBrief),
    parsedBrief,
  )
}
